# plot_results.py
# This script reads the filter_results.csv generated by the C++ application
# and visualizes the estimated annual volatility, number of components,
# and observed returns using matplotlib.


import pandas as pd
import matplotlib.pyplot as plt
import os
import sys

def generate_plots(csv_path):
    """
    Reads filter results from a CSV and plots the estimated volatility,
    number of components, and observed returns.

    Args:
        csv_path (str): The full or relative path to the filter_results.csv file.
    """
    if not os.path.exists(csv_path):
        print(f"Python Plotter Error: CSV file not found at '{csv_path}'.", file=sys.stderr)
        return False # Indicate failure

    try:
        # Read the CSV file, using tab as delimiter
        df = pd.read_csv(csv_path, sep='\t')
    except Exception as e:
        print(f"Python Plotter Error reading CSV file: {e}", file=sys.stderr)
        return False

    # Clean up column names by stripping whitespace
    df.columns = df.columns.str.strip()

    # Convert numeric columns, coercing errors will turn problematic values into NaN
    df['Day'] = pd.to_numeric(df['Day'], errors='coerce')
    df['Observed Return'] = pd.to_numeric(df['Observed Return'], errors='coerce')
    df['Filter Ann. Vol'] = pd.to_numeric(df['Filter Ann. Vol'], errors='coerce')
    df['# Components'] = pd.to_numeric(df['# Components'], errors='coerce')

    # Drop rows where critical numeric data is NaN (e.g., from parsing '""' or 'N/A')
    df.dropna(subset=['Day', 'Observed Return', 'Filter Ann. Vol', '# Components'], inplace=True)

    if df.empty:
        print("Python Plotter Error: No valid numeric data found in the CSV after parsing.", file=sys.stderr)
        return False

    # --- Plot 1: Estimated Annual Volatility & Number of Components ---
    fig1, ax1 = plt.subplots(figsize=(12, 6))

    # Plot Filter Ann. Vol on the primary Y-axis
    ax1.plot(df['Day'], df['Filter Ann. Vol'], color='blue', label='Estimated Annual Volatility (%)')
    ax1.set_xlabel('Day')
    ax1.set_ylabel('Annual Volatility (%)', color='blue')
    ax1.tick_params(axis='y', labelcolor='blue')
    ax1.grid(True, linestyle='--', alpha=0.7)

    # Create a second Y-axis for # Components
    ax2 = ax1.twinx()
    ax2.plot(df['Day'], df['# Components'], color='green', linestyle='--', label='Number of Components')
    ax2.set_ylabel('Number of Components', color='green')
    ax2.tick_params(axis='y', labelcolor='green')

    # Add title and legend
    ax1.set_title('Estimated Annual Volatility and Filter Components Over Time')
    # Combine legends from both axes
    lines, labels = ax1.get_legend_handles_labels()
    lines2, labels2 = ax2.get_legend_handles_labels()
    ax2.legend(lines + lines2, labels + labels2, loc='upper left')

    plt.tight_layout() # Adjust layout to prevent labels overlapping
    #plt.savefig('volatility_components_plot.png') # Uncomment to save the plot as an image

    # --- Plot 2: Observed Returns ---
    fig2, ax3 = plt.subplots(figsize=(12, 6))

    ax3.plot(df['Day'], df['Observed Return'], color='red', label='Observed Daily Log Return', alpha=0.7)
    ax3.set_xlabel('Day')
    ax3.set_ylabel('Log Return')
    ax3.set_title('Observed Daily Log Returns Over Time')
    ax3.grid(True, linestyle='--', alpha=0.7)
    ax3.legend()

    plt.tight_layout()
    #plt.savefig('observed_returns_plot.png') # Uncomment to save the plot as an image

    # Show both plots
    plt.show()

    return True # Indicate success

if __name__ == "__main__":

    print("Running plot_results.py directly for testing/debugging...", file=sys.stderr)
    # Default CSV path for direct testing
    test_csv_path = 'cmake-build-debug/filter_results.csv'
    if generate_plots(test_csv_path):
        print("Plots generated successfully.", file=sys.stderr)
    else:
        print("Failed to generate plots.", file=sys.stderr)
